const API_URL = process.env.API_URL ?? "http://localhost:4000";

async function request<T>(
  path: string,
  init?: RequestInit,
  cookie?: string
): Promise<T> {
  const res = await fetch(`${API_URL}${path}`, {
    ...init,
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
      ...(cookie ? { cookie } : {}),
      ...init?.headers,
    },
  });

  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    throw new Error(body.message ?? `Request failed (${res.status})`);
  }

  return (await res.json()) as T;
}

export interface User {
  id: string;
  name: string;
  email: string;
}

export const authApi = {
  signup: (input: { name: string; email: string; password: string }, cookie?: string) =>
    request<User>("/auth/signup", {
      method: "POST",
      body: JSON.stringify(input),
    }, cookie),
  login: (input: { email: string; password: string }, cookie?: string) =>
    request<User>("/auth/login", {
      method: "POST",
      body: JSON.stringify(input),
    }, cookie),
  logout: (cookie?: string) =>
    request<{ message: string }>("/auth/logout", undefined, cookie),
  me: (cookie?: string) => request<User>("/auth/me", undefined, cookie),
};

import { z } from "zod";

export const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
});

export const signupSchema = z.object({
  name: z.string().min(1),
  email: z.string().email(),
  password: z.string().min(8),
});

export type LoginInput = z.infer<typeof loginSchema>;
export type SignupInput = z.infer<typeof signupSchema>;

import { createServerFn } from "@tanstack/react-start";
import { getRequestHeader } from "@tanstack/react-start/server";
import { authApi } from "./api";
import { loginSchema, signupSchema } from "./validation";

export const loginFn = createServerFn({ method: "POST" })
  .validator(loginSchema)
  .handler(async ({ data }) => {
    const cookie = getRequestHeader("cookie");
    return authApi.login(data, cookie);
  });

export const signupFn = createServerFn({ method: "POST" })
  .validator(signupSchema)
  .handler(async ({ data }) => {
    const cookie = getRequestHeader("cookie");
    return authApi.signup(data, cookie);
  });

export const meFn = createServerFn({ method: "GET" }).handler(async () => {
  const cookie = getRequestHeader("cookie");
  try {
    return await authApi.me(cookie);
  } catch {
    return null;
  }
});

import { useState } from "react";
import { createFileRoute, useRouter } from "@tanstack/react-router";
import { loginFn } from "../lib/auth/server";

export const Route = createFileRoute("/login")({
  component: LoginPage,
});

function LoginPage() {
  const router = useRouter();
  const [error, setError] = useState<string | null>(null);

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);

    try {
      await loginFn({
        data: {
          email: String(form.get("email")),
          password: String(form.get("password")),
        },
      });
      router.navigate({ to: "/" });
    } catch (err) {
      setError((err as Error).message);
    }
  }

  return (
    <form onSubmit={onSubmit}>
      {error ? <p>{error}</p> : null}
      <input type="email" name="email" required />
      <input type="password" name="password" required />
      <button type="submit">Log in</button>
    </form>
  );
}
